/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

extern M2C_UNK gSlotValues;
extern M2C_UNK gSlotBackupValues;
extern M2C_UNK gSaveSlotValid;

/* For each of the 4 save slots marked valid, copies the backup value over the slot value. */ void restoreValidSlotValues(void) {
    s32 slot;

    slot = 0;
    do {
        if (((u16 *) &gSaveSlotValid)[(slot & 0xFFFF)] != 0) {
            ((u16 *) &gSlotValues)[(slot & 0xFFFF)] = ((u16 *) &gSlotBackupValues)[(slot & 0xFFFF)];
        }
        slot += 1;
    } while ((u32) (slot & 0xFFFF) < 4U);
}
